        "culturalNote_vi": "Ở Mỹ, công thức vàng khi gọi đồ là 'Can I get [món] [to go/for here]?'—ngắn gọn, thân thiện và lịch sự với từ 'please'. Không ai dùng 'I desire to purchase'.",
        "culturalNote_en": "In the US, 'Can I get [item] to go, please?' is the undisputed standard: friendly, crisp, and natural."
