        "culturalNote_vi": "'Shut up!' trong ngữ cảnh này hoàn toàn KHÔNG PHẢI là 'Im mồm', mà là biểu cảm giật mình kinh ngạc tột đỉnh tương đương với 'Thật á?! Đùa nhau à?!'.",
