          "phonetic": "Geumil jeonyeok chinmok domoreul wihan hoehabeul gajisigessseumnikka?",
          "translation_vi": "Liệu quý vị có muốn tổ chức một buổi hội họp nhằm mục đích vun đắp tình hữu nghị tối nay?",
          "translation_en": "Would you convene an assembly tonight for friendship promotion?",
