          "phonetic": "Annyeonghi gasipsio. Gwiha-ui musa gwigareul giwonhamnida.",
          "translation_vi": "Xin kính chúc quý vị ra về bình an. Nguyện cầu cho việc trở về nhà của quý vị được vô sự.",
          "translation_en": "Go in peace. I pray for your safe arrival at your residence.",
          "tag_vi": "Nghi lễ trang trọng",
          "tag_en": "Ceremonial Farewell"
