        "situation_en": "Expressing relief at lucky outcome",
        "usageTip_vi": "Ví dụ: '비가 많이 왔는데 다행히도 우산이 있었어' (Mưa to tầm tã nhưng may mà có mang ô).",
        "usageTip_en": "Highlights silver lining: 'Dahaenghido usani isseosseo' (Luckily I had an umbrella)."
