          "phonetic": "Fúwù rényuán, qǐngwèn shìfǒu néng wèi zàixià chéngshàng yí fèn shìliàng làdù de málàtàng shíwù yǐ gōng dǎbāo?",
          "translation_vi": "Kính thưa nhân viên phục vụ, liệu có thể dâng lên cho tại hạ một phần thức ăn ma lạt thang cay vừa phải để đóng gói?",
          "translation_en": "Service personnel, could you present a moderately spicy Malatang for takeout?",
